use Agah\Erp\Core\{Business,Ctx,Db,Jalali,Money,Request};
use Agah\Erp\Modules\Files\FileService;
use Agah\Erp\Modules\Payroll\PayrollService;
use Agah\Erp\Modules\Assets\AssetService;
if(!defined('ABSPATH'))exit;
$targetType=Request::str('get','target_type',10,'invoice');if(!isset(FileService::TARGETS[$targetType]))$targetType='invoice';$targetId=Request::int('get','target_id');$sourceQ=Request::str('get','source_q',100);$data=FileService::page($cid,Request::int('get','pg',1),Request::str('get','q',100),Request::str('get','category',80));
?>
<section class="erp-card"><h2>پیوست‌های خصوصی</h2><p>تصاویر JPEG، PNG، WebP و PDF ساده پذیرفته می‌شوند. PDF فقط دانلود می‌شود. دسترسی به پیوست، مجوز رکورد مبدأ را نیز لازم دارد.</p><p>سقف عملی آپلود این سرور: <?php echo esc_html(size_format(min(max(1,min(10,\Agah\Erp\Core\Settings::int('max_upload_mb')))*1048576,wp_max_upload_size()))); ?>؛ حداکثر ۵۰ فایل برای هر رکورد.</p><form method="get" class="erp-filter" action="<?php echo esc_url(agah_erp_url()); ?>"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="files"><?php self::input('q','جست‌وجوی نام یا دسته',Request::str('get','q',100));self::input('category','دسته دقیق (اختیاری)',Request::str('get','category',80)); ?><button type="submit" class="btn btn-outline">جست‌وجو</button></form><div class="erp-scroll"><table class="erp-table"><thead><tr><th>نام</th><th>دسته</th><th>حجم بایت</th><th>مبدأ</th><th>عملیات</th></tr></thead><tbody><?php foreach($data['rows'] as $f): ?><tr><td><?php echo esc_html($f['original_name']); ?></td><td><?php echo esc_html($f['category']); ?></td><td><?php echo esc_html(Money::toFa($f['byte_size'])); ?></td><td><?php foreach(FileService::TARGETS as $t=>$table)if($f[$t.'_id'])echo esc_html(['invoice'=>'فاکتور','voucher'=>'سند','party'=>'شخص','expense'=>'هزینه'][$t].' #'.$f[$t.'_id']); ?></td><td><a href="<?php echo esc_url(OperationsController::fileUrl($cid,$f['id'])); ?>">دانلود</a><?php if(strpos($f['mime'],'image/')===0): ?><details><summary>پیش‌نمایش تصویر</summary><img loading="lazy" style="max-width:240px;max-height:180px" alt="تصویر پیوست" src="<?php echo esc_url(OperationsController::fileUrl($cid,$f['id'],true)); ?>"></details><?php endif; ?><?php if(Ctx::can('file.delete')): ?><form method="post"><?php self::form('module_file_delete',$cid,$p,$f['id']); ?><button type="submit" class="btn btn-outline">حذف پیوست</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages($data['pages'],$data['page']); ?></section>
<?php if(Ctx::can('file.create')): ?><section class="erp-card"><h3>افزودن پیوست</h3><form method="get" action="<?php echo esc_url(agah_erp_url()); ?>" class="erp-filter"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="files"><?php self::select('target_type','نوع رکورد',['invoice'=>'فاکتور','voucher'=>'سند حسابداری','party'=>'شخص','expense'=>'هزینه و درآمد'],$targetType);self::input('source_q','جست‌وجوی نام، شرح یا شماره مبدأ',$sourceQ); ?><button type="submit" class="btn btn-outline">جست‌وجوی مبدأ</button></form><p>۱۰۰ نتیجه آخر نمایش داده می‌شود؛ برای یافتن رکورد قدیمی‌تر جست‌وجو کنید یا از صفحه همان رکورد، دکمه پیوست را بزنید.</p><form method="post" enctype="multipart/form-data" class="erp-form"><?php self::form('module_file_attach',$cid,$p);echo '<input type="hidden" name="target_type" value="'.esc_attr($targetType).'">';self::select('target_id','رکورد مبدأ',OperationsController::targets($cid,$targetType,$sourceQ,$targetId),$targetId);self::input('category','دسته‌بندی','','text','maxlength="80"'); ?><label>فایل<input type="file" name="attachment" accept=".jpg,.jpeg,.png,.webp,.pdf" required></label><button type="submit" class="btn btn-primary">آپلود خصوصی</button></form></section><?php endif; ?>
